package ui

const AdminEditorStatsCSS = `.editor-stats[hidden],[data-editor-stats][hidden],.seo-audit[hidden],[data-seo-audit][hidden],.page-weight-inspector[hidden],[data-page-weight][hidden]{display:none!important}.editor-stats{display:flex;gap:1rem;flex-wrap:wrap;padding:.65rem 1rem;color:var(--muted);font-size:.78rem}.editor-stats strong{color:var(--ink);font-variant-numeric:tabular-nums}.editor-stats .is-overused,.seo-audit .is-overused{color:var(--red,#dc2626);font-weight:700}.seo-audit{margin-top:.75rem;padding:.75rem 1rem;color:var(--muted);font-size:.82rem}.seo-audit h2{margin:0 0 .45rem;color:var(--ink);font-size:.95rem}.seo-audit ul{display:grid;gap:.25rem;margin:0;padding-inline-start:1.25rem}.editor-stats-docked{margin-top:.75rem;background:var(--bg-subtle);border:1px solid var(--line);border-radius:var(--radius-md);width:100%;box-sizing:border-box}.seo-audit-docked{margin-top:.75rem;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius-lg);box-shadow:var(--card-highlight)}.page-weight-inspector{position:static!important;right:auto!important;bottom:auto!important;z-index:auto!important;margin-top:.75rem;width:100%!important;max-height:none!important;border:1px solid var(--line);background:var(--surface);border-radius:var(--radius-lg);box-shadow:var(--card-highlight);padding:14px 18px;box-sizing:border-box}.page-weight-docked{position:static!important;margin-top:.75rem;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius-lg);box-shadow:var(--card-highlight);width:100%!important;right:auto!important;bottom:auto!important;z-index:auto!important}.page-weight-inspector[data-weight-state="fast"] [data-page-weight-state]{color:var(--green,#15803d)}.page-weight-inspector[data-weight-state="moderate"] [data-page-weight-state]{color:var(--amber,#b45309)}.page-weight-inspector[data-weight-state="heavy"] [data-page-weight-state]{color:var(--red,#dc2626);font-weight:700}`

const AdminEditorStatsJS = `(()=>{const textOf=e=>e?.value??e?.innerText??e?.textContent??'',set=(root,selector,ok,message)=>{const el=root.querySelector(selector);if(el){el.textContent=(ok?'✓ ':'• ')+message;el.classList.toggle('is-overused',!ok)}return ok};const update=()=>{const bar=document.querySelector('[data-editor-stats]'),audit=document.querySelector('[data-seo-audit]'),weight=document.querySelector('[data-page-weight]');if(!bar||!audit)return;const editor=document.querySelector('.richtext-editor .ql-editor,.richtext-editor[contenteditable="true"],textarea[name="body"]');if(!editor){bar.hidden=true;audit.hidden=true;if(weight)weight.hidden=true;return}const host=editor.closest('.richtext-field, .richtext-wrap, label')||editor.parentElement;if(host&&bar.parentElement!==host){host.appendChild(bar);bar.classList.add('editor-stats-docked')}const sideCol=document.querySelector('.editor-side-col');if(sideCol&&audit.parentElement!==sideCol){sideCol.appendChild(audit);audit.classList.add('seo-audit-docked')}if(sideCol&&weight&&weight.parentElement!==sideCol){sideCol.appendChild(weight);weight.classList.add('page-weight-docked')}bar.hidden=false;audit.hidden=false;const text=textOf(editor),words=text.trim().match(/\S+/gu)||[];bar.querySelector('[data-editor-words]').textContent=String(words.length);bar.querySelector('[data-editor-characters]').textContent=String(text.length);bar.querySelector('[data-editor-reading-time]').textContent=String(Math.max(1,Math.ceil(words.length/200)));const keyword=document.querySelector('[name="focus_keyword"],[name="keyword"]'),wrap=bar.querySelector('[data-editor-keyword-wrap]');if(keyword?.value.trim()){const needle=keyword.value.trim().toLocaleLowerCase(),matches=words.filter(word=>word.replace(/[^\p{L}\p{N}]/gu,'').toLocaleLowerCase()===needle).length,density=words.length?matches/words.length*100:0;bar.querySelector('[data-editor-keyword-density]').textContent=density.toFixed(1)+'%';wrap.hidden=false;wrap.classList.toggle('is-overused',density>3)}else{wrap.hidden=true;wrap.classList.remove('is-overused')}const title=document.querySelector('[name="seo_title"],[name="title"]'),description=document.querySelector('[name="seo_description"],[name="description"],[name="excerpt"]'),titleLength=Array.from(textOf(title).trim()).length,descriptionLength=Array.from(textOf(description).trim()).length,checks=[];checks.push(set(audit,'[data-seo-title]',titleLength>=30&&titleLength<=60,'Başlık '+titleLength+' karakter (öneri 30–60)'));checks.push(set(audit,'[data-seo-description]',descriptionLength>=120&&descriptionLength<=160,'Açıklama '+descriptionLength+' karakter (öneri 120–160)'));const doc=editor.matches('.ql-editor')?editor:new DOMParser().parseFromString(text,'text/html'),headings=[...doc.querySelectorAll('h1,h2,h3,h4,h5,h6')].map(h=>Number(h.tagName.slice(1))),hasH1=headings.includes(1),skipped=headings.some((n,i)=>i>0&&n>headings[i-1]+1);checks.push(set(audit,'[data-seo-heading]',hasH1&&!skipped,hasH1?(skipped?'Başlık seviyelerinde atlama var':'Başlık yapısı uygun'):'H1 başlığı eksik'));const images=[...doc.querySelectorAll('img')],missingAlt=images.filter(img=>!img.getAttribute('alt')?.trim()).length;checks.push(set(audit,'[data-seo-alt]',missingAlt===0,missingAlt?missingAlt+' görselde açıklama eksik':'Görsel açıklamaları mevcut'));const sentences=text.split(/[.!?]+/u).filter(s=>s.trim()).length,average=sentences?words.length/sentences:words.length;checks.push(set(audit,'[data-seo-readability]',average<=25,average?Math.round(average)+' kelime/cümle ortalaması':'İçerik ekleyin'));audit.querySelector('[data-seo-score]').textContent=checks.filter(Boolean).length+'/5'};document.addEventListener('input',event=>{if(event.target.closest('.richtext-editor,textarea,[name="title"],[name="seo_title"],[name="seo_description"],[name="description"],[name="excerpt"],[name="focus_keyword"],[name="keyword"]'))update()});document.addEventListener('hydro:admin-navigated',update);update()})();`
